// ===========================================================================
//  Zeus Wizard - single-file Cloudflare Worker (no npm, no build, no GitHub)
//  Paste into  Workers & Pages > Create > Hello World > Edit code  and deploy.
//  Optional: add a Secret named SECRET (enables the one-click "private link").
//  Generated by tools/build-wizard-worker.py  -  front-end lives in web/assets/*
//
//  Features
//   - Deploy ANY .js file (link or uploaded file) on Workers or Pages with a D1 database bound to it
//     (BPB / Zeus builds additionally get their embedded settings injected - everything else is uploaded as-is)
//   - Deploy source: any https link to a .js file (GitHub "blob" links are converted), managed in the browser
//   - Two-step deploy (optional switch): source 1 is deployed first, source 2 is uploaded over it right after (same Worker + D1 binding)
//   - Runtime Placement: Default / Smart / Region (AWS, GCP, Azure) incl. countries
//   - Panel link name: random or custom worker name
//   - Manage: scan the account (Workers + Pages), see D1 bindings, update in place without losing
//     bindings / settings, change placement, delete (the D1 database is deleted together with it)
//   - Download: pick any Workers of the account (filter + checkboxes) and download their scripts, no dashboard needed
// ===========================================================================
const WORKER_URL = 'https://raw.githubusercontent.com/Alireza58310/old-new/refs/heads/main/bbbb/worker.js';
const CF_API = 'https://api.cloudflare.com/client/v4';
const INDEX_HTML = /*__INDEX_HTML__*/ '';

const MAX_NAME = 50;
const PLACEMENT_RE = /^(aws|gcp|azure):[a-z0-9-]{3,40}$/;
const SCRIPT_NAME_RE = /^[A-Za-z0-9][A-Za-z0-9_-]{0,62}$/;

/* ----------------------------- helpers ----------------------------------- */
function randString(charset, minLen, maxLen) {
    const length = Math.floor(Math.random() * (maxLen - minLen + 1)) + minLen;
    const arr = new Uint8Array(length);
    crypto.getRandomValues(arr);
    let s = '';
    for (let i = 0; i < length; i++) s += charset[arr[i] % charset.length];
    return s;
}
const randInt = (min, max) => Math.floor(Math.random() * (max - min + 1)) + min;
function randSubdomain() {
    const charset = 'abcdefghijklmnopqrstuvwxyz0123456789-';
    let s;
    do { s = randString(charset, 16, 32); } while (s.startsWith('-') || s.endsWith('-'));
    return s;
}
function randCode() {
    const charset = 'abcdefghijklmnopqrstuvwxyz0123456789';
    // random prefix: letter/underscore first so generated names are always valid identifiers, never two the same run
    const prefixes = ['__var', '__tmp', '__cfg', '__val', '_x', '_n', '__o', '__q'];
    const pick = (arr) => arr[randInt(0, arr.length - 1)];
    let out = '';
    for (let i = 0, n = randInt(50, 500); i < n; i++) out += `let ${pick(prefixes)}_${randString(charset, 8, 16)}_${i} = ${randInt(0, 99999)};\n`;
    for (let i = 0, n = randInt(50, 500); i < n; i++) out += `function ${pick(prefixes)}_${randString(charset, 8, 16)}_${i}() { return ${randInt(0, 999)}; }\n`;
    return out;
}

/* ------------------------- deploy-time obfuscation ------------------------
 * Applied to every script this wizard actually uploads (link, file, BPB/Zeus
 * or plain) so "Edit code" in the Cloudflare dashboard never shows the real
 * logic - only the decoy junk plus one base64 blob that is decoded at runtime.
 * Simple regex-based rename/wrap (same spirit as randCode() above), not a
 * real parser: good enough for a single trusted source file, not a guarantee
 * against a determined attacker.
 * ------------------------------------------------------------------------- */

// Detector: identifiers that look like decoy/renamed names - either this very
// wizard's own randCode() output from an earlier deploy, or another tool's
// similarly-shaped names (__var_xxxxx_0, __m123456, _a1b2c3, ...). Used to
// re-randomize a file that already carries such a signature instead of
// leaving a stable, fingerprintable name set across redeploys.
const JUNK_ID_RE = /\b(?:__var|__func|__tmp|__cfg|__val|__m|__o|__q|_x|_n)_[0-9a-zA-Z]{3,16}(?:_\d+)?\b/g;

function scanJunkIdentifiers(code) {
    const found = new Map();
    JUNK_ID_RE.lastIndex = 0;
    let m;
    while ((m = JUNK_ID_RE.exec(code))) found.set(m[0], (found.get(m[0]) || 0) + 1);
    return found;
}

function freshJunkName() {
    const prefixes = ['__var', '__tmp', '__cfg', '__val', '_x', '_n', '__o', '__q'];
    const charset = 'abcdefghijklmnopqrstuvwxyz0123456789';
    const pick = (arr) => arr[randInt(0, arr.length - 1)];
    return `${pick(prefixes)}_${randString(charset, 8, 16)}_${randInt(0, 999999)}`;
}
const reEscape = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

// Gives every detected id above a brand-new random name (whole-word, every occurrence).
function rerandomizeIdentifiers(code, ids) {
    let out = code;
    const used = new Set();
    for (const id of ids) {
        let next;
        do { next = freshJunkName(); } while (used.has(next));
        used.add(next);
        out = out.replace(new RegExp(`\\b${reEscape(id)}\\b`, 'g'), next);
    }
    return out;
}

// Renames the script's own top-level `const`/`let NAME =` declarations to __mNNNNNN,
// consistently across the file (every reference, since it's a flat word-replace).
// Only matches declarations starting at column 0, so nested/local names are untouched.
function renameTopLevelDeclarations(code) {
    const re = /^(?:const|let)\s+([A-Za-z_$][A-Za-z0-9_$]*)\s*=/gm;
    const names = new Set();
    let m;
    while ((m = re.exec(code))) names.add(m[1]);
    if (!names.size) return code;
    // Object.create(null): a plain {} inherits Object.prototype, so a declared name like
    // "toString" or "constructor" would silently look up the native method instead of
    // being treated as "not renamed" - this avoids that trap.
    const mapping = Object.create(null);
    for (const name of [...names].sort((a, b) => b.length - a.length)) mapping[name] = `__m${randInt(100000, 999999)}`;
    return code.replace(/\b[A-Za-z_$][A-Za-z0-9_$]*\b/g, (w) => (w in mapping ? mapping[w] : w));
}

function utf8ToBase64(str) {
    const bytes = new TextEncoder().encode(str);
    let binary = '';
    for (let i = 0; i < bytes.length; i++) binary += String.fromCharCode(bytes[i]);
    return btoa(binary);
}

// Peels every top-level `import ... from "...";` line off the front (a Function()
// body can't use `import`), base64-encodes the rest, and rebuilds a loader that
// decodes + runs it, re-exposing whatever those imports bound as call arguments.
// A trailing `export default EXPR;` becomes `return EXPR;` inside the hidden body.
function wrapBase64Loader(code) {
    const importRe = /^import\s+(?:([A-Za-z_$][\w$]*)|(?:\*\s+as\s+([A-Za-z_$][\w$]*))|\{([^}]*)\})\s+from\s+["']([^"']+)["'];?\s*\r?\n/;
    let header = '', body = code, bindings = [];
    for (; ;) {
        const m = body.match(importRe);
        if (!m) break;
        header += m[0];
        if (m[1]) bindings.push(m[1]);
        else if (m[2]) bindings.push(m[2]);
        else if (m[3]) for (const part of m[3].split(',')) {
            const piece = part.trim();
            if (!piece) continue;
            const as = piece.match(/^(.+?)\s+as\s+(.+)$/);
            bindings.push(as ? as[2].trim() : piece);
        }
        body = body.slice(m[0].length);
    }
    // anchored to column 0 so an "export default ..." that merely appears inside a string/template
    // literal elsewhere in the file (e.g. example code shown in the panel's own UI) isn't touched.
    // IMPORTANT: module evaluation does NOT stop at `export default` - any top-level declarations
    // written after it in the source still run (and get hoisted). Converting it straight to a bare
    // `return` would cut the function off right there and silently skip all of that later code -
    // exactly the bug that caused this. So the exported value is captured in a variable instead,
    // and only returned once every remaining statement has actually executed.
    const exportVar = '_' + randString('0123456789abcdef', 6, 6);
    const hasExportDefault = /^export\s+default\s+/m.test(body);
    if (hasExportDefault) {
        body = body.replace(/^export\s+default\s+/m, `var ${exportVar} = `);
        body = body.replace(/\s*$/, '') + `\nreturn ${exportVar};\n`;
    }
    const b64 = utf8ToBase64(body);
    const v1 = '_' + randString('0123456789abcdef', 6, 6);
    const v2 = '_' + randString('0123456789abcdef', 6, 6);
    const ctorArgs = [...bindings.map((b) => JSON.stringify(b)), v1].join(',');
    let out = `${header}var ${v1}=new TextDecoder("utf-8").decode(Uint8Array.from(atob("${b64}"),function(c){return c.charCodeAt(0);}));\n` +
        `var ${v2}=new Function(${ctorArgs})(${bindings.join(',')});\n`;
    // a classic service-worker-format script (addEventListener("fetch", ...), no export at all)
    // already took effect when the line above ran - nothing to export, so don't fake one
    if (hasExportDefault) out += `export default ${v2};\n`;
    return out;
}

// Full pipeline, run on every script this wizard uploads:
//  1) detector - re-randomize any decoy/renamed ids already present (ours or another tool's)
//  2) rename the script's own top-level declarations
//  3) wrap the result in the base64 runtime-decode loader
//  4) surround with fresh decoy junk (before AND after)
function obfuscateForDeploy(code) {
    const junk = scanJunkIdentifiers(code);
    let out = junk.size ? rerandomizeIdentifiers(code, [...junk.keys()]) : code;
    out = renameTopLevelDeclarations(out);
    out = wrapBase64Loader(out);
    return [randCode(), out, randCode()].join('\n');
}
// shuffles a flat object's key order - same data, different byte layout once JSON.stringify'd
function shuffleKeys(obj) {
    const keys = Object.keys(obj);
    for (let i = keys.length - 1; i > 0; i--) { const j = randInt(0, i);[keys[i], keys[j]] = [keys[j], keys[i]]; }
    const out = {};
    for (const k of keys) out[k] = obj[k];
    return out;
}
const today = () => new Date().toISOString().split('T')[0];

const enc = new TextEncoder(), dec = new TextDecoder();
async function aesKey(secret) {
    const hash = await crypto.subtle.digest('SHA-256', enc.encode(secret));
    return crypto.subtle.importKey('raw', hash, 'AES-GCM', false, ['encrypt', 'decrypt']);
}
async function encrypt(text, secret) {
    const key = await aesKey(secret), iv = crypto.getRandomValues(new Uint8Array(12));
    const data = new Uint8Array(await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, key, enc.encode(text)));
    const all = new Uint8Array(iv.length + data.length);
    all.set(iv); all.set(data, iv.length);
    return btoa(String.fromCharCode(...all));
}
async function decrypt(b64, secret) {
    try {
        const key = await aesKey(secret), bytes = Uint8Array.from(atob(b64), c => c.charCodeAt(0));
        return dec.decode(await crypto.subtle.decrypt({ name: 'AES-GCM', iv: bytes.slice(0, 12) }, key, bytes.slice(12)));
    } catch { throw new Error('The private link is invalid or SECRET changed. Open the wizard main page and use a new token.'); }
}

function createStreamLogger() {
    const { readable, writable } = new TransformStream();
    const writer = writable.getWriter(), e = new TextEncoder();
    const send = (type, message) => writer.write(e.encode(JSON.stringify({ type, message }) + '\n'));
    return {
        readable,
        success: m => send('success', m), info: m => send('info', m), warn: m => send('warn', m),
        error: m => send('error', m), complete: m => send('complete', m),
        close: () => writer.close()
    };
}

/* worker / project name typed by the user -> a safe slug (a-z, 0-9, -) */
function sanitizeName(raw) {
    if (!raw || typeof raw !== 'string') return '';
    let n = raw.trim().toLowerCase().replace(/[^a-z0-9-]+/g, '-').replace(/-+/g, '-').replace(/^-+|-+$/g, '');
    if (n.length > MAX_NAME) n = n.slice(0, MAX_NAME).replace(/-+$/g, '');
    return n;
}

/* ---------------------------- deploy source ------------------------------ */
// Any https link to a .js file. The "blob" links people copy from GitHub / GitLab are converted to raw links.
function normalizeSourceUrl(raw) {
    const s = String(raw ?? '').trim();
    if (!s) return WORKER_URL;
    let u;
    try { u = new URL(s); } catch { throw new Error('The source link is not a valid URL.'); }
    if (u.protocol !== 'https:') throw new Error('The source link must start with https://');
    const host = u.hostname.toLowerCase();
    if (!host.includes('.') || /^[0-9.]+$/.test(host) || host.startsWith('[') || host.endsWith('.local') || host.endsWith('.internal')) throw new Error('The source link must use a public domain name.');
    if (host === 'github.com') {
        const m = u.pathname.match(/^\/([^/]+)\/([^/]+)\/(?:blob|raw)\/(.+)$/);
        if (m) return `https://raw.githubusercontent.com/${m[1]}/${m[2]}/${m[3]}`;
        throw new Error('This GitHub link does not point to a file (expected github.com/user/repo/blob/branch/file.js).');
    }
    if (host === 'gitlab.com') {
        const m = u.pathname.match(/^\/(.+?)\/-\/(?:blob|raw)\/(.+)$/);
        if (m) return `https://gitlab.com/${m[1]}/-/raw/${m[2]}`;
    }
    return u.origin + u.pathname + u.search;
}

// builds made for this wizard (BPB / Zeus) take embedded settings; every other script is uploaded untouched
const isBpbBuild = (code) => code.startsWith('Object.assign(globalThis') || code.includes('EMBEDED_SETTINGS');
// ES module (export default ...) or classic service worker (addEventListener('fetch', ...))
const isModuleCode = (code) => /(^|[\n;}])\s*(export\s+(default|\{|const|let|var|function|async|class)|import\s*[\w{*'"])/.test(code);
const MAX_SCRIPT_BYTES = 10 * 1024 * 1024;
function validateScript(script, what) {
    if (!script || !script.trim()) throw new Error(`${what} is empty.`);
    if (script.length > MAX_SCRIPT_BYTES) throw new Error(`${what} is larger than 10 MB.`);
    if (/^\s*<(!doctype|html)/i.test(script)) throw new Error(`${what} is an HTML page, not a .js file.`);
}

function detectVersion(text) {
    const pats = [
        /CURRENT_VERSION\s*[=:]\s*['"]v?([0-9][0-9.]*)['"]/i,
        /id=["']panel-version["'][^>]*>\s*v?([0-9][0-9.]*)\s*</i,
        /\bPANEL_VERSION\s*[=:]\s*['"]v?([0-9][0-9.]*)['"]/i,
        /\bVERSION\s*=\s*['"]v?([0-9]+\.[0-9][0-9.]*)['"]/
    ];
    for (const re of pats) { const m = re.exec(text); if (m) return 'v' + m[1]; }
    return '';
}

/* --------------------------- source verification ------------------------- */
// Counts { } ( ) [ ] the way a JS parser would: braces inside strings, template text, comments and regex
// literals are ignored (a plain character count gets those wrong). Also reports unterminated strings/comments.
function scanCode(code) {
    const n = code.length, count = { '{': 0, '}': 0, '(': 0, ')': 0, '[': 0, ']': 0 };
    const CLOSER = { '{': '}', '(': ')', '[': ']' };
    const stack = [], tmpl = [], problems = [];
    const lineOf = (idx) => code.slice(0, idx).split('\n').length;
    const REGEX_PREV = '(,=:[!&|?{};+-*%<>~^';
    const REGEX_WORDS = new Set(['return', 'typeof', 'instanceof', 'in', 'of', 'new', 'delete', 'void', 'throw', 'case', 'do', 'else', 'yield', 'await']);
    const special = /[{}()\[\]\/"'`]/g;
    let i = 0;

    // is a "/" at idx the start of a regex literal (true) or a division (false)? decided by what came before it
    const regexAllowed = (idx) => {
        let j = idx - 1;
        while (j >= 0 && /\s/.test(code[j])) j--;
        if (j < 0) return true;
        const c = code[j];
        if (REGEX_PREV.includes(c)) return true;
        if (/[A-Za-z_$]/.test(c)) { let k = j; while (k >= 0 && /[\w$]/.test(code[k])) k--; return REGEX_WORDS.has(code.slice(k + 1, j + 1)); }
        return false;
    };
    // template text; returns true when the template ended, false when a ${ opened code again
    const template = () => {
        const t = /[\\`$]/g;
        for (; ;) {
            t.lastIndex = i;
            const m = t.exec(code);
            if (!m) { problems.push(`unterminated template literal`); i = n; return true; }
            i = m.index;
            if (code[i] === '\\') { i += 2; continue; }
            if (code[i] === '`') { i++; return true; }
            if (code[i] === '$' && code[i + 1] === '{') { i += 2; stack.push('}'); tmpl.push(stack.length); count['{']++; return false; }
            i++;
        }
    };

    while (i < n) {
        special.lastIndex = i;
        const m = special.exec(code);
        if (!m) break;
        i = m.index;
        const ch = code[i];
        if (ch === '/') {
            const nx = code[i + 1];
            if (nx === '/') { const e = code.indexOf('\n', i); i = e < 0 ? n : e; continue; }
            if (nx === '*') { const e = code.indexOf('*/', i + 2); if (e < 0) { problems.push(`unterminated comment at line ${lineOf(i)}`); break; } i = e + 2; continue; }
            if (regexAllowed(i)) {
                const start = i; let cls = false; i++;
                for (; i < n; i++) {
                    const d = code[i];
                    if (d === '\\') { i++; continue; }
                    if (d === '\n') { problems.push(`unterminated regex at line ${lineOf(start)}`); break; }
                    if (cls) { if (d === ']') cls = false; } else if (d === '[') cls = true; else if (d === '/') break;
                }
                i++;
                continue;
            }
            i++;
            continue;
        }
        if (ch === '"' || ch === "'") {
            const start = i; i++;
            while (i < n && code[i] !== ch) {
                if (code[i] === '\\') i++;
                else if (code[i] === '\n') { problems.push(`unterminated string at line ${lineOf(start)}`); break; }
                i++;
            }
            i++;
            continue;
        }
        if (ch === '`') { i++; template(); continue; }
        if (ch in CLOSER) { stack.push(CLOSER[ch]); count[ch]++; i++; continue; }
        // closing bracket
        if (ch === '}' && tmpl.length && tmpl[tmpl.length - 1] === stack.length && stack[stack.length - 1] === '}') {
            stack.pop(); tmpl.pop(); count['}']++; i++; template(); continue;     // end of ${ ... } inside a template
        }
        count[ch]++;
        const expected = stack.pop();
        if (expected !== ch && problems.length < 5) problems.push(`unexpected "${ch}" at line ${lineOf(i)}`);
        i++;
    }
    if (stack.length) problems.push(`${stack.length} bracket(s) never closed at the end of the file`);
    const balanced = problems.length === 0 && count['{'] === count['}'] && count['('] === count[')'] && count['['] === count[']'];
    return {
        balanced, problems,
        braces: [count['{'], count['}']], parens: [count['('], count[')']], brackets: [count['['], count[']']],
        raw: [(code.match(/\{/g) || []).length, (code.match(/\}/g) || []).length]      // naive count, for comparison
    };
}

const toHex = (buf) => [...new Uint8Array(buf)].map(b => b.toString(16).padStart(2, '0')).join('');

// size, lines, SHA-256 and bracket balance of a script; throws (unless allowUnverified) when it looks truncated or corrupt
async function verifyScript(script, { sha256 = '', allowUnverified = false } = {}) {
    const bytes = enc.encode(script);
    const scan = scanCode(script);
    const digest = toHex(await crypto.subtle.digest('SHA-256', bytes));
    const issues = [];
    if (!scan.balanced) {
        const bad = [['braces { }', scan.braces], ['parentheses ( )', scan.parens], ['brackets [ ]', scan.brackets]].filter(([, c]) => c[0] !== c[1]);
        issues.push(`unbalanced ${bad.map(([k, c]) => `${k}: ${c[0]} open / ${c[1]} closed`).join(', ') || 'syntax'}${scan.problems.length ? ` (${scan.problems.join('; ')})` : ''}`);
    }
    const expected = String(sha256 ?? '').trim().toLowerCase().replace(/^sha-?256\s*[:=-]?\s*/, '');
    if (expected) {
        if (!/^[0-9a-f]{64}$/.test(expected)) throw new Error('The expected SHA-256 must be 64 hex characters.');
        if (expected !== digest) issues.push(`SHA-256 mismatch (expected ${expected.slice(0, 12)}…, got ${digest.slice(0, 12)}…)`);
    }
    const junkIds = scanJunkIdentifiers(script);
    const check = {
        ok: issues.length === 0, issues, size: bytes.length, lines: script.split('\n').length, sha256: digest,
        checksum: expected ? (expected === digest ? 'matched' : 'mismatch') : 'none',
        braces: scan.braces, parens: scan.parens, brackets: scan.brackets, raw: scan.raw,
        junkIdentifiers: junkIds.size
    };
    if (issues.length && !allowUnverified) throw new Error(`Source verification failed: ${issues.join('; ')}. Nothing was deployed. (Use “Install even if verification fails” only if you are sure the file is fine.)`);
    return check;
}
const describeCheck = (c) => `${(c.size / 1024).toFixed(0)} KB · ${c.lines} lines · SHA-256 ${c.sha256.slice(0, 12)}… · { } ${c.braces[0]}/${c.braces[1]} · ( ) ${c.parens[0]}/${c.parens[1]} · [ ] ${c.brackets[0]}/${c.brackets[1]}` +
    (c.raw[0] !== c.raw[1] || c.raw[0] !== c.braces[0] ? ` (plain count { ${c.raw[0]}/${c.raw[1]}: braces inside strings, regex and comments are ignored)` : '') + (c.checksum === 'matched' ? ' · checksum matched ✓' : '') +
    (c.junkIdentifiers ? ` · ⚠ ${c.junkIdentifiers} decoy identifier(s) detected in the source (will be re-randomized on deploy)` : '');

async function fetchSource(raw, opts = {}) {
    const url = normalizeSourceUrl(raw);
    const res = await fetch(`${url}${url.includes('?') ? '&' : '?'}t=${Date.now()}`, { headers: { 'Cache-Control': 'no-cache' } });
    if (!res.ok) throw new Error(`Failed to get the script: status ${res.status} at ${url}`);
    const script = await res.text();
    validateScript(script, `The file at ${url}`);
    const check = await verifyScript(script, opts);
    return { script, url, version: detectVersion(script), bpb: isBpbBuild(script), check };
}

/* ------------------------ read what is inside a panel -------------------- */
// The first `const EMBEDED_SETTINGS = {...}` of a build made by this wizard; parsed with a string-aware brace scanner.
function extractEmbedded(text) {
    const m = /const\s+EMBEDED_SETTINGS\s*=\s*\{/.exec(text || '');
    if (!m) return null;
    const start = m.index + m[0].length - 1;
    let depth = 0, inStr = false, esc = false;
    for (let k = start; k < text.length && k < start + 30000; k++) {
        const c = text[k];
        if (inStr) { if (esc) esc = false; else if (c === '\\') esc = true; else if (c === '"') inStr = false; continue; }
        if (c === '"') inStr = true;
        else if (c === '{') depth++;
        else if (c === '}' && --depth === 0) { try { return JSON.parse(text.slice(start, k + 1)); } catch { return null; } }
    }
    return null;
}
function detectBuildDate(text) {
    const m = /^\/\/ Build: (\S+)/m.exec((text || '').slice(0, 400));
    return m ? m[1] : '';
}

/* ----------------------------- placement --------------------------------- */
// '' | 'default' -> none, 'smart' -> {mode:'smart'}, 'aws:us-east-1' -> {region:'aws:us-east-1'}
function parsePlacement(v) {
    const s = String(v ?? '').trim().toLowerCase();
    if (!s || s === 'default' || s === 'off') return null;
    if (s === 'smart') return { mode: 'smart' };
    if (PLACEMENT_RE.test(s)) return { region: s };
    throw new Error(`Invalid Runtime Placement value: ${v}`);
}
function cleanPlacement(p) {
    if (!p || typeof p !== 'object') return null;
    if (p.region) return { region: p.region };
    if (p.hostname) return { hostname: p.hostname };
    if (p.host) return { host: p.host };
    if (p.mode && p.mode !== 'off') return { mode: p.mode };
    return null;
}
function placementString(p) {
    p = cleanPlacement(p);
    if (!p) return '';
    if (p.region) return p.region;
    if (p.mode) return p.mode;
    if (p.hostname) return 'hostname:' + p.hostname;
    return 'host:' + p.host;
}
const looksLikePlacementError = (err) => /placement|region/i.test(err?.message ?? '');

/* ------------------------ Cloudflare REST client ------------------------- */
class CFAccount {
    constructor(token, id, email) { this.token = token; this.id = id; this.email = email; }

    static async request(token, method, path, body) {
        const res = await fetch(CF_API + path, {
            method,
            headers: { Authorization: `Bearer ${token}`, ...(body instanceof FormData || body === undefined ? {} : { 'Content-Type': 'application/json' }) },
            body: body === undefined || body instanceof FormData ? body : JSON.stringify(body)
        });
        let data = {};
        try { data = await res.json(); } catch { }
        if (!res.ok || data.success === false) {
            const errs = Array.isArray(data.errors) ? data.errors : [];
            const err = new Error(errs.length ? errs.map(e => `${e.message ?? JSON.stringify(e)}${e.code ? ` (code ${e.code})` : ''}`).join('; ') : `HTTP ${res.status}`);
            err.code = errs[0]?.code;
            err.status = res.status;
            throw err;
        }
        return data.result;
    }

    static async create(token) {
        const v = await CFAccount.request(token, 'GET', '/user/tokens/verify');
        if (v.status !== 'active') throw new Error(`API token is ${v.status}.`);

        const accounts = await CFAccount.request(token, 'GET', '/accounts');
        if (!accounts.length) throw new Error('No account found for this token (is "Account Settings: Read" in the token?).');

        // the account e-mail is the panel login name (and is written into the worker); "admin" only if the token cannot read it
        let email = 'admin';
        try { const u = await CFAccount.request(token, 'GET', '/user'); if (u.email) email = u.email.toLowerCase(); } catch { }

        return new CFAccount(token, accounts[0].id, email);
    }

    api(method, path, body) { return CFAccount.request(this.token, method, `/accounts/${this.id}${path}`, body); }

    async nameTaken(deployType, name) {
        const exists = async (path) => (await fetch(`${CF_API}/accounts/${this.id}${path}`, { headers: { Authorization: `Bearer ${this.token}` } })).status === 200;
        try {
            if (deployType === 'pages' && await exists(`/pages/projects/${name}`)) return true;
            return await exists(`/workers/scripts/${name}`);
        } catch { return false; }
    }

    async createD1Database(workerName, deployType) {
        const base = `${workerName}-${deployType}`.slice(0, 60);
        let lastErr;
        for (let i = 0; i < 3; i++) {
            // a database with the same name may be left over from an earlier panel -> retry with a random suffix
            const name = i === 0 ? base : `${base.slice(0, 52)}-${randString('0123456789abcdef', 6, 6)}`;
            try { const id = (await this.api('POST', '/d1/database', { name })).uuid; this.lastD1Name = name; return id; }
            catch (err) {
                lastErr = err;
                if (!(err.code === 7502 || /already exists|already taken/i.test(err.message))) break;
            }
        }
        throw new Error(`Error creating D1 database (does the token have "D1: Edit"?): ${lastErr.message}`);
    }

    async getWorkersDevSubdomain() { return `${(await this.api('GET', '/workers/subdomain')).subdomain}.workers.dev`; }

    async createWorkersDevSubdomain() {
        for (let i = 0; i < 3; i++) {
            try { return (await this.api('PUT', '/workers/subdomain', { subdomain: randSubdomain() })).subdomain + '.workers.dev'; } catch { }
        }
        throw new Error('Failed to create a unique workers.dev subdomain after 3 attempts.');
    }

    /* ---- workers ---- */
    async putWorker(name, code, metadata) {
        const form = new FormData();
        const isModule = isModuleCode(code);
        const md = { ...metadata };
        if (!isModule) { delete md.main_module; md.body_part = 'worker.js'; }     // classic service-worker script
        form.append('metadata', new Blob([JSON.stringify(md)], { type: 'application/json' }));
        form.append('worker.js', new Blob([code], { type: isModule ? 'application/javascript+module' : 'application/javascript' }), 'worker.js');
        return this.api('PUT', `/workers/scripts/${name}`, form);
    }

    // uploads; if Cloudflare refuses only because of the placement value, uploads again without it and reports a warning
    async putWorkerSafe(name, code, metadata) {
        try { await this.putWorker(name, code, metadata); return ''; }
        catch (err) {
            if (!metadata.placement || !looksLikePlacementError(err)) throw err;
            const { placement, ...rest } = metadata;
            await this.putWorker(name, code, rest);
            return `Cloudflare did not accept the Runtime Placement (${placementString(placement)}): ${err.message}. The panel was uploaded with Default placement.`;
        }
    }

    async deployWorker(name, code, databaseId, placement, binding = 'DB') {
        const metadata = {
            main_module: 'worker.js',
            compatibility_date: today(),
            compatibility_flags: ['nodejs_compat'],
            bindings: [{ type: 'd1', name: binding, id: databaseId }]
        };
        if (placement) metadata.placement = placement;
        try { return await this.putWorkerSafe(name, code, metadata); }
        catch (err) { throw new Error(`Error deploying worker: ${err.message}`); }
    }

    // Cloudflare can leave a brand-new script "dead" right after its first creation
    // (route not yet activated) - a second, identical upload reliably fixes it.
    async reuploadWorker(name, code, metadata) {
        try { await this.putWorker(name, code, metadata); return true; }
        catch { return false; }
    }

    // best-effort: the workers.dev route is usually already enabled by the PUT above;
    // if Cloudflare's confirmation call fails, the panel still works, so never abort for this.
    async enableSubdomainSafe(name) {
        try { await this.api('POST', `/workers/scripts/${name}/subdomain`, { enabled: true, previews_enabled: true }); return ''; }
        catch (err) { return err.message ?? String(err); }
    }
    enableSubdomain(name) { return this.api('POST', `/workers/scripts/${name}/subdomain`, { enabled: true, previews_enabled: true }); }

    // the deployed module(s): multipart for ES modules, plain text for service workers
    async getScriptText(name) {
        const res = await fetch(`${CF_API}/accounts/${this.id}/workers/scripts/${name}`, { headers: { Authorization: `Bearer ${this.token}` } });
        if (!res.ok) { const e = new Error(`Cannot read Worker "${name}" (HTTP ${res.status}).`); e.status = res.status; throw e; }
        if (/multipart\/form-data/i.test(res.headers.get('content-type') || '')) {
            try {
                const fd = await res.clone().formData();
                let best = '', parts = 0;
                for (const [, v] of fd) { const t = typeof v === 'string' ? v : await v.text(); parts++; if (t.length > best.length) best = t; }
                if (best) return { text: best, parts };
            } catch { }
        }
        return { text: await res.text(), parts: 1 };
    }

    // every module of the deployed Worker as base64 (ES modules come back multipart, a service worker as plain text)
    async getScriptParts(name) {
        const res = await fetch(`${CF_API}/accounts/${this.id}/workers/scripts/${name}`, { headers: { Authorization: `Bearer ${this.token}` } });
        if (!res.ok) { const e = new Error(`Cannot read Worker "${name}" (HTTP ${res.status}).`); e.status = res.status; throw e; }
        const b64 = (buf) => { const u = new Uint8Array(buf); let s = ''; for (let i = 0; i < u.length; i += 0x8000) s += String.fromCharCode(...u.subarray(i, i + 0x8000)); return btoa(s); };
        if (/multipart\/form-data/i.test(res.headers.get('content-type') || '')) {
            try {
                const fd = await res.clone().formData();
                const parts = [];
                for (const [key, v] of fd) parts.push({ name: String(typeof v === 'string' ? key : (v.name || key)), data: b64(typeof v === 'string' ? enc.encode(v) : await v.arrayBuffer()) });
                if (parts.length) return parts;
            } catch { }
        }
        return [{ name: 'worker.js', data: b64(await res.arrayBuffer()) }];
    }

    // bindings + the settings we must carry over when the script is uploaded again
    async scriptSettings(name) {
        let s = null;
        try { s = await this.api('GET', `/workers/scripts/${name}/settings`); } catch { }
        let bindings = Array.isArray(s?.bindings) ? s.bindings : null;
        if (!bindings) {
            try { const b = await this.api('GET', `/workers/scripts/${name}/bindings`); if (Array.isArray(b)) bindings = b; } catch { }
        }
        return {
            bindings,
            compatibility_date: s?.compatibility_date,
            compatibility_flags: s?.compatibility_flags,
            placement: cleanPlacement(s?.placement),
            observability: s?.observability,
            limits: s?.limits
        };
    }

    /* ---- pages ---- */
    async createPagesProject(name, databaseId, binding = 'DB') {
        const project = await this.api('POST', '/pages/projects', {
            name,
            production_branch: 'main',
            deployment_configs: {
                production: {
                    compatibility_date: today(),
                    compatibility_flags: ['nodejs_compat'],
                    d1_databases: { [binding]: { id: databaseId } }
                }
            }
        });
        return project.subdomain ?? '';
    }

    deployPages(name, code) {
        const form = new FormData();
        form.append('manifest', '{}');
        form.append('branch', 'main');
        form.append('_worker.js', new Blob([code], { type: 'application/javascript+module' }), '_worker.js');
        return this.api('POST', `/pages/projects/${name}/deployments`, form);
    }

    // Pages Runtime Placement lives in the project's deployment configs (Pages has no metadata upload)
    async patchPagesPlacement(name, placement) {
        await this.api('PATCH', `/pages/projects/${name}`, { deployment_configs: { production: { placement }, preview: { placement } } });
    }

    // every Pages project of the account, with its D1 bindings
    async listPages() {
        const projects = await this.api('GET', '/pages/projects?per_page=100');
        return (projects ?? []).map(p => {
            const dbs = p.deployment_configs?.production?.d1_databases ?? {};
            return {
                name: p.name, kind: 'pages',
                subdomain: p.subdomain ?? '', domains: p.domains ?? [],
                created: p.created_on ?? '', modified: p.latest_deployment?.created_on ?? '',
                d1s: Object.entries(dbs).map(([binding, v]) => ({ binding, id: v?.id ?? '' })).filter(x => x.id),
                placement: placementString(p.deployment_configs?.production?.placement)
            };
        });
    }

    async listD1Names() {
        const dbs = await this.api('GET', '/d1/database?per_page=1000');
        return Object.fromEntries((dbs ?? []).map(d => [d.uuid ?? d.id, d.name]));
    }
}

/* ------------------------- build the deployable file --------------------- */
const pathCharset = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456780-_';
const passCharset = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@$&*_-+;:,.';

function freshSettings(account, mainDomain, securePath) {
    return {
        accID: account.id, accEmail: account.email, apiToken: account.token,
        vlUUID: crypto.randomUUID(), trPass: randString(passCharset, 16, 20), securePath: securePath || randString(pathCharset, 12, 16),
        proxyIpMode: 'proxyip', proxyIPs: [], prefixes: [], fallback: '', dohUrl: '',
        mainDomain
    };
}
function buildCode(script, embeded, email) {
    // settings object is shuffled, then the whole thing (settings + real script) goes
    // through the deploy-time obfuscator - varies every single deploy
    const assembled = `// ${email}\n// Build: ${new Date().toISOString()}\n// @ts-nocheck\nconst EMBEDED_SETTINGS = ${JSON.stringify(shuffleKeys(embeded))};${script}`;
    return obfuscateForDeploy(assembled);
}
// BPB / Zeus builds get their embedded settings; any other script is run through the
// same deploy-time obfuscator so "Edit code" never shows real logic either way
async function buildScript(account, mainDomain, opts) {
    let script, url, version, check;
    const vopts = { sha256: opts.sha256, allowUnverified: opts.allowUnverified };
    if (opts.scriptText) {
        script = opts.scriptText; url = ''; version = detectVersion(script);
        validateScript(script, `The uploaded file "${opts.scriptName || 'script.js'}"`);
        check = await verifyScript(script, vopts);
    } else ({ script, url, version, check } = await fetchSource(opts.sourceUrl, vopts));
    if (!isBpbBuild(script)) return { code: obfuscateForDeploy(script), path: '', sourceUrl: url, version, bpb: false, check };
    const embeded = freshSettings(account, mainDomain);
    return { code: buildCode(script, embeded, account.email), path: embeded.securePath, sourceUrl: url, version, bpb: true, check };
}

/* ----------------------------- deploy flows ------------------------------ */
async function resultPayload(env, account, p) {
    return { ...p, user: account.email, key: env.SECRET ? await encrypt(account.token, env.SECRET) : '' };
}
const urls = (host, built) => built.bpb ? { url: `https://${host}/${built.path}/panel`, zeus: `https://${host}/${built.path}/zeus` } : { url: `https://${host}/`, zeus: '' };
const sleep = (ms) => new Promise(r => setTimeout(r, ms));
// Two-step deploy: source 1 (a throw-away / stub script) goes up first, source 2 (the real one) is uploaded over it right after.
// If source 1 cannot be loaded the deploy is NOT aborted: source 2 is simply deployed on its own.
async function buildFirstStep(account, host, opts, { success, warn }) {
    if (!opts.firstSourceUrl) return null;
    try {
        const b = await buildScript(account, host, { sourceUrl: opts.firstSourceUrl, sha256: opts.firstSha256, allowUnverified: opts.allowUnverified });
        (b.check.ok ? success : warn)(`Source 1 ${b.check.ok ? 'verified' : 'NOT verified (' + b.check.issues.join('; ') + ')'}: ${describeCheck(b.check)}`);
        return b;
    } catch (err) {
        warn(`Source 1 could not be loaded (${err.message ?? err}). Skipping it and deploying source 2 directly.`);
        return null;
    }
}
const sourceLabel = (built, opts) => built.sourceUrl || (opts.scriptName ? `file: ${opts.scriptName}` : '');

async function deployPages(env, account, workerName, databaseId, opts, { success, warn, complete }) {
    const stub = await buildFirstStep(account, `${workerName}.pages.dev`, opts, { success, warn });
    const built = await buildScript(account, `${workerName}.pages.dev`, opts);
    (built.check.ok ? success : warn)(`${stub ? 'Source 2' : 'Source'} ${built.check.ok ? 'verified' : 'NOT verified (' + built.check.issues.join('; ') + ')'}: ${describeCheck(built.check)}`);
    success(built.bpb ? 'Script built successfully (BPB / Zeus settings embedded)!' : 'Script ready (uploaded as-is)!');
    const subdomain = await account.createPagesProject(workerName, databaseId, opts.d1Binding);
    success('Pages project created successfully!');
    if (stub) {
        await account.deployPages(workerName, stub.code);
        success('Step 1/2: source 1 deployed.');
        await sleep(opts.stepDelayMs ?? 2000);
    }
    await account.deployPages(workerName, built.code);
    success(stub ? 'Step 2/2: source 2 deployed over source 1.' : 'Pages deployed successfully!');
    if (opts.placement) {
        try { await account.patchPagesPlacement(workerName, opts.placement); success(`Runtime Placement applied: ${placementString(opts.placement)}`); }
        catch (err) { warn(`Cloudflare did not accept the Runtime Placement for Pages (${err.message}). It works with Default placement.`); }
    }
    complete(JSON.stringify(await resultPayload(env, account, {
        name: workerName, kind: 'pages', label: opts.label || workerName, sourceUrl: sourceLabel(built, opts), placement: placementString(opts.placement),
        d1Binding: opts.d1Binding, d1: { binding: opts.d1Binding, id: databaseId, name: account.lastD1Name ?? '' }, bpb: built.bpb, ...urls(subdomain, built)
    })));
}

async function deployWorkers(env, account, workerName, databaseId, opts, { success, warn, complete }) {
    let subdomain;
    try { subdomain = await account.getWorkersDevSubdomain(); success('Account workers subdomain is available!'); }
    catch { subdomain = await account.createWorkersDevSubdomain(); success('Fresh account, Workers subdomain created successfully!'); }

    const stub = await buildFirstStep(account, `${workerName}.${subdomain}`, opts, { success, warn });
    const built = await buildScript(account, `${workerName}.${subdomain}`, opts);
    (built.check.ok ? success : warn)(`${stub ? 'Source 2' : 'Source'} ${built.check.ok ? 'verified' : 'NOT verified (' + built.check.issues.join('; ') + ')'}: ${describeCheck(built.check)}`);
    success(built.bpb ? 'Script built successfully (BPB / Zeus settings embedded)!' : 'Script ready (uploaded as-is)!');
    const warning = await account.deployWorker(workerName, (stub || built).code, databaseId, opts.placement, opts.d1Binding);
    success(stub ? 'Step 1/2: source 1 deployed.' : 'Worker deployed successfully!');
    if (warning) warn(warning); else if (opts.placement) success(`Runtime Placement applied: ${placementString(opts.placement)}`);

    // re-upload once more: Cloudflare can leave a first creation "dead" on a brand-new script/subdomain
    const reMetadata = {
        main_module: 'worker.js', compatibility_date: today(), compatibility_flags: ['nodejs_compat'],
        bindings: [{ type: 'd1', name: opts.d1Binding, id: databaseId }], ...(warning ? {} : (opts.placement ? { placement: opts.placement } : {}))
    };
    if (stub) {
        // step 2: the real script goes over source 1 (same Worker, same D1 binding)
        await sleep(opts.stepDelayMs ?? 2000);
        try { await account.putWorker(workerName, built.code, reMetadata); }
        catch (err) { throw new Error(`Step 2 (source 2) failed: ${err.message ?? err}. Source 1 is still deployed on \"${workerName}\".`); }
        success('Step 2/2: source 2 deployed over source 1.');
    } else if (await account.reuploadWorker(workerName, built.code, reMetadata)) success('Script re-created cleanly.');
    else warn('Re-creating the script did not confirm, continuing anyway.');

    const subErr = await account.enableSubdomainSafe(workerName);
    if (subErr) warn(`workers.dev route confirm failed - continuing (${subErr})`);
    else success('Worker subdomain enabled successfully!');
    complete(JSON.stringify(await resultPayload(env, account, {
        name: workerName, kind: 'workers', label: opts.label || workerName, sourceUrl: sourceLabel(built, opts), placement: warning ? '' : placementString(opts.placement),
        d1Binding: opts.d1Binding, d1: { binding: opts.d1Binding, id: databaseId, name: account.lastD1Name ?? '' }, bpb: built.bpb, ...urls(`${workerName}.${subdomain}`, built)
    })));
}

/* ------------------------- panel detection / management ------------------ */
// Describes any Worker of the account: bindings, D1 databases, placement and, for BPB / Zeus builds, the panel link.
// The content is only downloaded for Workers that have a D1 binding (those are the ones this wizard deploys).
async function inspectWorker(account, name, devSub, d1Names = {}) {
    try {
        const settings = await account.scriptSettings(name).catch(() => ({ bindings: null }));
        if (!settings.bindings && !(await account.getScriptText(name).then(() => true, () => false))) return null;   // no such Worker
        const bindings = settings.bindings ?? [];
        const d1s = bindings.filter(b => b.type === 'd1').map(b => { const id = b.id ?? b.database_id ?? ''; return { binding: b.name, id, name: d1Names[id] ?? '' }; });
        let text = '';
        if (d1s.length) { try { text = (await account.getScriptText(name)).text; } catch { } }
        const embedded = extractEmbedded(text);
        const securePath = embedded?.securePath ?? '';
        const host = devSub ? `${name}.${devSub}` : (embedded?.mainDomain ?? '');
        const base = host && securePath ? `https://${host}/${securePath}` : '';
        return {
            name, kind: 'workers',
            family: embedded ? 'bpb-zeus-d1' : 'generic',
            version: detectVersion(text),
            build: detectBuildDate(text),
            securePath,
            embeddedDomain: embedded?.mainDomain ?? '',
            email: embedded?.accEmail ?? '',
            d1s,
            bindings: bindings.map(b => `${b.type}:${b.name}`),
            placement: placementString(settings.placement),
            bindingsKnown: !!settings.bindings,
            url: base ? `${base}/panel` : (host ? `https://${host}/` : ''),
            zeus: base ? `${base}/zeus` : ''
        };
    } catch { return null; }
}

function bindingsForUpload(bindings) {
    // secrets are never returned by Cloudflare: they are kept through `keep_bindings`
    return bindings.filter(b => b.type !== 'secret_text' && b.type !== 'secret_key').map(b =>
        b.type === 'd1' ? { type: 'd1', name: b.name, id: b.id ?? b.database_id } : b);
}

async function updateWorkerPanel(account, name, body) {
    const mode = body.mode === 'reapply' || body.mode === 'placement' ? 'reapply' : 'update';
    const [settings, script] = await Promise.all([account.scriptSettings(name), account.getScriptText(name)]);
    if (!settings.bindings) throw new Error('Could not read the Worker bindings. Aborted so nothing is lost.');

    let code, version = '', sourceUrl = '', warning = '', checkInfo = null;
    if (mode === 'reapply') {
        if (script.parts > 1) throw new Error('This Worker has several modules, it can only be updated from a source.');
        code = script.text;
        version = detectVersion(code);
    } else {
        const src = await fetchSource(body.sourceUrl, { sha256: body.sha256, allowUnverified: !!body.allowUnverified });
        const embedded = extractEmbedded(script.text);
        version = src.version; sourceUrl = src.url; checkInfo = src.check;
        if (!src.bpb) code = obfuscateForDeploy(src.script);                // any other script: obfuscated for deploy, bindings are kept
        else if (embedded) {                                                // BPB / Zeus on BPB / Zeus: same link, UUID, password
            if (embedded.accID === account.id) embedded.apiToken = account.token;
            code = buildCode(src.script, embedded, embedded.accEmail || account.email);
        } else {                                                            // a BPB / Zeus build over a different script: nothing to keep
            const devSub = await account.getWorkersDevSubdomain().catch(() => '');
            code = buildCode(src.script, freshSettings(account, devSub ? `${name}.${devSub}` : ''), account.email);
            warning = 'The previous script had no BPB / Zeus settings, so a new panel path, UUID and password were generated.';
        }
    }

    const placement = body.placement === undefined || body.placement === 'keep' ? settings.placement : parsePlacement(body.placement);
    const metadata = {
        main_module: 'worker.js',
        compatibility_date: settings.compatibility_date || today(),
        compatibility_flags: settings.compatibility_flags?.length ? settings.compatibility_flags : ['nodejs_compat'],
        bindings: bindingsForUpload(settings.bindings),
        keep_bindings: ['secret_text', 'secret_key']
    };
    if (placement) metadata.placement = placement;
    if (settings.observability && typeof settings.observability.enabled === 'boolean') {
        metadata.observability = { enabled: settings.observability.enabled };
        if (typeof settings.observability.head_sampling_rate === 'number') metadata.observability.head_sampling_rate = settings.observability.head_sampling_rate;
    }
    if (settings.limits && typeof settings.limits.cpu_ms === 'number') metadata.limits = { cpu_ms: settings.limits.cpu_ms };

    const placementWarning = await account.putWorkerSafe(name, code, metadata);
    return { name, kind: 'workers', mode, version, sourceUrl, check: checkInfo, build: detectBuildDate(code), placement: placementWarning ? '' : placementString(placement), warning: [warning, placementWarning].filter(Boolean).join(' ') };
}

async function updatePagesPanel(account, name, body) {
    const project = await account.api('GET', `/pages/projects/${name}`);
    const placementOnly = body.mode === 'placement' || body.mode === 'reapply';
    let warning = '', url = '', zeus = '', regenerated = false, version = '', sourceUrl = '', checkInfo = null;

    if (!placementOnly) {
        // The deployed _worker.js of a Pages project cannot be downloaded, so BPB / Zeus settings cannot be read back.
        // The panel path is kept when the browser knows it (saved link); UUID / password are regenerated.
        const keepPath = typeof body.securePath === 'string' && /^[A-Za-z0-9_-]{6,40}$/.test(body.securePath) ? body.securePath : '';
        const src = await fetchSource(body.sourceUrl, { sha256: body.sha256, allowUnverified: !!body.allowUnverified });
        version = src.version; sourceUrl = src.url; checkInfo = src.check;
        if (src.bpb) {
            const embedded = freshSettings(account, project.subdomain, keepPath);
            await account.deployPages(name, buildCode(src.script, embedded, account.email));
            regenerated = true;
            const base = `https://${project.subdomain}/${embedded.securePath}`;
            url = `${base}/panel`; zeus = `${base}/zeus`;
        } else {
            await account.deployPages(name, obfuscateForDeploy(src.script));
            url = `https://${project.subdomain}/`;
        }
    }

    let placement = project.deployment_configs?.production?.placement ?? null;
    if (body.placement !== undefined && body.placement !== 'keep') {
        placement = parsePlacement(body.placement);
        try { await account.patchPagesPlacement(name, placement ?? {}); }
        catch (err) { warning = `Cloudflare did not accept the Runtime Placement for Pages (${err.message}).`; placement = null; }
    }
    return { name, kind: 'pages', mode: placementOnly ? 'placement' : 'update', version, sourceUrl, check: checkInfo, url, zeus, regenerated, placement: placementString(placement), warning };
}

// Deletes the Worker / Pages project and, unless deleteDb === false, every D1 database bound to it.
async function deletePanel(account, name, body) {
    const withDb = body.deleteDb !== false;
    let ids = [];
    if (withDb) {
        // read the bindings BEFORE the project disappears; refuse to delete the panel if they cannot be read
        if (body.kind === 'pages') {
            const dbs = (await account.api('GET', `/pages/projects/${name}`)).deployment_configs?.production?.d1_databases ?? {};
            ids = Object.values(dbs).map(v => v?.id).filter(Boolean);
        } else {
            const s = await account.scriptSettings(name);
            if (!s.bindings) throw new Error('Could not read the bindings of this Worker, so its D1 database cannot be found. Nothing was deleted.');
            ids = s.bindings.filter(b => b.type === 'd1').map(b => b.id ?? b.database_id).filter(Boolean);
        }
    }
    if (body.kind === 'pages') await account.api('DELETE', `/pages/projects/${name}`);
    else await account.api('DELETE', `/workers/scripts/${name}?force=true`);

    const deletedDbs = [], warnings = [];
    for (const id of [...new Set(ids)]) {
        try { await account.api('DELETE', `/d1/database/${id}`); deletedDbs.push(id); }
        catch (err) { warnings.push(`D1 database ${id} could not be deleted: ${err.message}`); }
    }
    return { name, deleted: true, dbDeleted: deletedDbs.length > 0, deletedDbs, warning: warnings.join(' ') };
}

/* -------------------------------- router --------------------------------- */
const json = (obj, status = 200) => new Response(JSON.stringify(obj), { status, headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' } });

async function resolveToken(url, env, body) {
    const key = url.searchParams.get('key');
    if (key) {
        if (!env.SECRET) throw new Error('Private links need a Secret named SECRET on this wizard.');
        return decrypt(key, env.SECRET);
    }
    const t = String(body?.token ?? '').trim();
    if (!t) throw new Error('API token is empty.');
    return t;
}

async function api(request, url, env, fn) {
    if (request.headers.get('Origin') !== url.origin) return new Response('Unauthorized context', { status: 403 });
    try {
        const body = await request.json().catch(() => ({}));
        return json({ success: true, ...(await fn(body)) });
    } catch (err) {
        return json({ success: false, error: err.message ?? String(err) }, 400);
    }
}
async function withAccount(url, env, body) { return CFAccount.create(await resolveToken(url, env, body)); }
function scriptName(raw) {
    const n = String(raw ?? '').trim();
    if (!SCRIPT_NAME_RE.test(n)) throw new Error('Invalid Worker / project name.');
    return n;
}

export default {
    async fetch(request, env) {
        const url = new URL(request.url);
        const post = request.method === 'POST';

        if (url.pathname === '/api/deploy' && post) {
            if (request.headers.get('Origin') !== url.origin) return new Response('Unauthorized context', { status: 403 });

            const logger = createStreamLogger();
            const { readable, info, error, success, close } = logger;

            (async () => {
                try {
                    const key = url.searchParams.get('key');
                    const form = await request.formData();
                    if (key && !env.SECRET) throw new Error('Private links need a Secret named SECRET on this wizard.');
                    const apiToken = key ? await decrypt(key, env.SECRET) : (form.get('apiToken')?.toString().trim() ?? '');
                    const deployType = form.get('deployType')?.toString() === 'pages' ? 'pages' : 'workers';
                    const file = form.get('scriptFile');
                    const d1Binding = (form.get('d1Binding')?.toString().trim() || 'DB');
                    if (!/^[A-Za-z_][A-Za-z0-9_]{0,62}$/.test(d1Binding)) throw new Error('The D1 binding name must be a valid variable name (letters, digits, _).');
                    const opts = {
                        d1Binding,
                        scriptText: file && typeof file !== 'string' && file.size ? await file.text() : '',
                        scriptName: file && typeof file !== 'string' ? String(file.name || '').slice(0, 80) : '',
                        sourceUrl: form.get('sourceUrl')?.toString().trim() ?? '',
                        sha256: form.get('sha256')?.toString().trim() ?? '',
                        firstSourceUrl: form.get('firstSourceUrl')?.toString().trim() ?? '',
                        firstSha256: form.get('firstSha256')?.toString().trim() ?? '',
                        stepDelayMs: (() => { const v = parseFloat(form.get('stepDelay')?.toString() ?? ''); return Number.isFinite(v) ? Math.min(15000, Math.max(0, v * 1000)) : 2000; })(),
                        allowUnverified: form.get('allowUnverified')?.toString() === '1',
                        placement: parsePlacement(form.get('placement')?.toString()),
                        label: (form.get('label')?.toString() ?? '').trim().slice(0, 80)
                    };
                    const customName = form.get('customName')?.toString() ?? '';
                    const cleanName = sanitizeName(customName);
                    if (customName.trim() && !cleanName) throw new Error('The panel link name must contain Latin letters or digits.');
                    const account = await CFAccount.create(apiToken);

                    let workerName;
                    if (cleanName) {
                        if (await account.nameTaken(deployType, cleanName)) throw new Error(`The name "${cleanName}" is already used by a Worker / Pages project in this account. Choose another name.`);
                        workerName = cleanName;
                        success(`Using the link name "${workerName}"`);
                    } else {
                        do { workerName = randSubdomain(); } while (await account.nameTaken(deployType, workerName));
                    }

                    info('Installing...');
                    const databaseId = await account.createD1Database(workerName, deployType);
                    success('D1 database created successfully!');

                    if (deployType === 'pages') await deployPages(env, account, workerName, databaseId, opts, logger);
                    else await deployWorkers(env, account, workerName, databaseId, opts, logger);
                } catch (err) {
                    error(`Failed to install: ${err.message ?? err}`);
                } finally {
                    close();
                }
            })();

            return new Response(readable, { headers: { 'Content-Type': 'application/x-ndjson' } });
        }

        // test a deploy source (no token needed)
        if (url.pathname === '/api/check-source' && post) return api(request, url, env, async (body) => {
            const { script, url: finalUrl, version, bpb, check } = await fetchSource(body.sourceUrl, { sha256: body.sha256, allowUnverified: true });
            return { url: finalUrl, size: script.length, version, bpb, check, format: isModuleCode(script) ? 'module' : 'service-worker' };
        });

        // step 1 of the scan: account, workers.dev subdomain, every Worker name and the Pages candidates
        if (url.pathname === '/api/panels/list' && post) return api(request, url, env, async (body) => {
            const account = await withAccount(url, env, body);
            let devSub = '';
            try { devSub = await account.getWorkersDevSubdomain(); } catch { }
            const scripts = (await account.api('GET', '/workers/scripts') ?? [])
                .map(s => ({ name: s.id, modified: s.modified_on ?? '', created: s.created_on ?? '' }))
                .sort((a, b) => String(b.modified).localeCompare(String(a.modified)));
            let pages = [], pagesError = '', d1Names = {};
            try { pages = await account.listPages(); } catch (err) { pagesError = err.message; }
            try { d1Names = await account.listD1Names(); } catch { }
            for (const p of pages) for (const d of p.d1s) d.name = d1Names[d.id] ?? '';
            return { account: { id: account.id, email: account.email }, devSub, scripts, pages, pagesError, d1Names };
        });

        // step 2: inspect a small batch (each Worker costs 2-3 API calls, a request may only make 50 on the free plan)
        if (url.pathname === '/api/panels/inspect' && post) return api(request, url, env, async (body) => {
            const account = await withAccount(url, env, body);
            const names = [...new Set((Array.isArray(body.names) ? body.names : []).map(scriptName))].slice(0, 8);
            const devSub = /^[a-z0-9-]+\.workers\.dev$/i.test(body.devSub ?? '') ? body.devSub : '';
            const d1Names = body.d1Names && typeof body.d1Names === 'object' ? body.d1Names : {};
            const panels = (await Promise.all(names.map(n => inspectWorker(account, n, devSub, d1Names)))).filter(Boolean);
            return { checked: names.length, panels };
        });

        // download the script(s) of Workers straight from the account (a few per request: each one costs API calls)
        if (url.pathname === '/api/panels/download' && post) return api(request, url, env, async (body) => {
            const account = await withAccount(url, env, body);
            const names = [...new Set((Array.isArray(body.names) ? body.names : []).map(scriptName))].slice(0, 5);
            if (!names.length) throw new Error('No Worker selected.');
            const files = await Promise.all(names.map(async (name) => {
                try { return { name, parts: await account.getScriptParts(name) }; }
                catch (err) { return { name, error: err.message ?? String(err) }; }
            }));
            return { files };
        });

        if (url.pathname === '/api/panels/update' && post) return api(request, url, env, async (body) => {
            const account = await withAccount(url, env, body);
            const name = scriptName(body.name);
            return body.kind === 'pages' ? updatePagesPanel(account, name, body) : updateWorkerPanel(account, name, body);
        });

        if (url.pathname === '/api/panels/delete' && post) return api(request, url, env, async (body) => {
            const account = await withAccount(url, env, body);
            return deletePanel(account, scriptName(body.name), body);
        });

        if (url.pathname === '/' || url.pathname === '/index.html') {
            return new Response(INDEX_HTML.replaceAll('%%DEFAULT_SOURCE%%', WORKER_URL), { headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' } });
        }
        return new Response('Not found', { status: 404 });
    }
};
